export const OFFICIAL_BENCHMARK_FIXTURES = Object.freeze(Object.values(RAW_FIXTURES).map((fixture) => Object.freeze({
  ...fixture,
  geometry: decodeGeometry(fixture.geometryGzipBase64Chunks)
})));
